"""simulates 100 dice rolls, counts each face, and prints a histogram"""
import random
import sys


def simulates_dice_rolls():
    """simulates 100 dice rolls"""
    rolls = [0] * 6  
    for _ in range(100):
        roll = random.randint(1, 6)
        rolls[roll-1] += 1 
    return rolls

def counts_face(previous):
    """counts each face"""
    counts = {}
    for face in previous:
        if face in counts:
            counts[face] += 1
        else:
            counts[face] = 1
    return counts

def prints_histogram(previous):
    """prints a histogram"""
    counts = previous.items()
    histogram = {}
    for count in counts:
        histogram[count[0]] = count[1]
    for i in histogram.keys():
      print(f"Count of {i}: {histogram[i]}")
    return histogram

def main():
    r1 = simulates_dice_rolls()
    print(f"[step 1 simulates_dice_rolls] {type(r1).__name__}: {repr(r1)[:120]}", file=sys.stderr)
    r2 = counts_face(r1)
    print(f"[step 2 counts_face] {type(r2).__name__}: {repr(r2)[:120]}", file=sys.stderr)
    r3 = prints_histogram(r2)
    print(f"[step 3 prints_histogram] {type(r3).__name__}: {repr(r3)[:120]}", file=sys.stderr)
    return r3


if __name__ == "__main__":
    main()

